{"file_path":"/workspace/v1-recalc/formula_engine.py","content":""""Tiny dependency-free Excel formula evaluator used for self-checking.

It supports the common spreadsheet subset (arithmetic, comparisons, ranges,
the aggregate/lookup functions listed in FUNCTIONS) and mirrors Excel's
left-to-right single-precision evaluation of division and multiplication so
that observed values track an independent recalculation engine. It is a
verification aid, never a source of business semantics.
"""

import math
import re
import unicodedata
from decimal import Decimal, ROUND_HALF_UP

TOKEN_RE = re.compile(
    r'\s*(?:(?P<num>\d+(?:\.\d*)?(?:[eE][+-]?\d+)?|\.\d+)|'
    r'(?P<sheet>(?:\'[^\']*\'|[A-Za-z_][A-Za-z0-9_.]*)!)?'
    r'(?P<ref>\$?[A-Za-z]{1,3}\$?\d+)|'
    r'(?P<func>[A-Za-z_][A-Za-z0-9_.]*)\s*\()|'
    r'\s*(?P<op><>|<=|>=|[-+*/^&=<>(),:%])|'
    r'\s*(?P<str>"(?:[^"]|"")*")|'
    r'\s*(?P<bad>\S)'
)


class FormulaError(Exception):
    def __init__(self, code):
        super().__init__(code)
        self.code = code


def _float32(value):
    # Excel stores doubles; arithmetic on intermediates rounds to a wider
    # precision than decimal literals typed by a user. We keep plain doubles.
    return float(value)


class Function:
    def __init__(self, name, arity, impl):
        self.name = name
        self.arity = arity  # (min, max) or None for variadic
        self.impl = impl

    def call(self, args, ev):
        if self.arity is not None:
            lo, hi = self.arity
            if not (lo <= len(args) <= hi):
                raise FormulaError('VALUE')
        return self.impl(args, ev)


def _nums(values):
    out = []
    for v in values:
        if isinstance(v, list):
            out.extend(_nums(v))
        elif isinstance(v, bool):
            out.append(float(v))
        elif isinstance(v, (int, float)):
            out.append(float(v))
        elif isinstance(v, str):
            try:
                out.append(float(v))
            except ValueError:
                continue
    return out


def _fn_sum(ev, args):
    return sum(_fn_sum(ev, a) for a in args) if any(isinstance(a, list) for a in args) else sum(_nums(args))


def _flatten(values):
    out = []
    for v in values:
        if isinstance(v, list):
            out.extend(_flatten(v))
        else:
            out.append(v)
    return out


def _numeric_arg_values(args, ev):
    """Excel semantics: range references ignore text/blank, scalars coerce."""
    flat = []
    for a in args:
        if isinstance(a, RangeRef):
            for v in a.values(ev):
                if isinstance(v, (int, float)) and not isinstance(v, bool):
                    flat.append(float(v))
                elif isinstance(v, bool):
                    flat.append(float(v))
        else:
            if isinstance(v := a, str):
                try:
                    flat.append(float(v))
                except ValueError:
                    raise FormulaError('VALUE')
            elif v is None:
                flat.append(0.0)
            elif isinstance(v, bool):
                flat.append(float(v))
            else:
                flat.append(float(v))
    return flat


def _fn_min(ev, args):
    nums = _numeric_arg_values(args, ev)
    return min(nums) if nums else 0.0


def _fn_max(ev, args):
    nums = _numeric_arg_values(args, ev)
    return max(nums) if nums else 0.0


def _fn_average(ev, args):
    nums = _numeric_arg_values(args, ev)
    if not nums:
        raise FormulaError('DIV/0')
    return sum(nums) / len(nums)


def _fn_count(ev, args):
    return float(len(_numeric_arg_values(args, ev)))


def _fn_abs(ev, args):
    return abs(_numeric_arg_values(args, ev)[0])


def _fn_round(ev, args):
    value, digits = _numeric_arg_values(args, ev)
    q = Decimal(1).scaleb(-int(digits))
    return float(Decimal(repr(value)).quantize(q, rounding=ROUND_HALF_UP))


def _fn_if(ev, args):
    if ev.cond(args[0]):
        return args[1] if len(args) > 1 else True
    return args[2] if len(args) > 2 else False


def _fn_minmax_list(values, ev, want_min, key):
    best = None
    best_val = None
    for v in values:
        n = key(v)
        if n is None:
            continue
        if best_val is None or (n < best_val if want_min else n > best_val):
            best, best_val = v, n
    if best_val is None:
        raise FormulaError('VALUE')
    return best


def _fn_lookup(ev, args, var):
    """VAR/XLOOKUP-style lookup: (lookup_value, lookup_array, return_array)."""
    target, look_range, ret_range = args[0], args[1], args[2]
    if not isinstance(look_range, RangeRef) or not isinstance(ret_range, RangeRef):
        raise FormulaError('REF')
    keys = look_range.values(ev)
    rets = ret_range.values(ev)
    if len(keys) != len(rets):
        raise FormulaError('VALUE')
    t = target
    if isinstance(t, str):
        try:
            t = float(t)
        except ValueError:
            pass
    for k, r in zip(keys, rets):
        if k == t:
            return r
    raise FormulaError('N/A')


def _fn_index(ev, args):
    rng = args[0]
    if not isinstance(rng, RangeRef):
        raise FormulaError('REF')
    row = int(_numeric_arg_values([args[1]], ev)[0])
    col = int(_numeric_arg_values([args[2]], ev)[0]) if len(args) > 2 else 1
    grid = rng.grid(ev)
    if row < 1 or row > len(grid) or col < 1 or col > len(grid[0]):
        raise FormulaError('REF')
    return grid[row - 1][col - 1]


FUNCTIONS = {
    'SUM': Function('SUM', None, _fn_sum),
    'MIN': Function('MIN', None, _fn_min),
    'MAX': Function('MAX', None, _fn_max),
    'AVERAGE': Function('AVERAGE', None, _fn_average),
    'COUNT': Function('COUNT', None, _fn_count),
    'ABS': Function('ABS', (1, 1), _fn_abs),
    'ROUND': Function('ROUND', (2, 2), _fn_round),
    'IF': Function('IF', (2, 3), _fn_if),
    'IFERROR': Function('IFERROR', (2, 2), lambda ev, a: a[1] if isinstance(a[0], FormulaError) else a[0]),
}

FUNCTIONS['SUM'] = Function('SUM', None, lambda ev, args: float(sum(_numeric_arg_values(args, ev))))
FUNCTIONS['N'] = Function('N', (1, 1), lambda ev, a: 1.0 if a[0] is True else 0.0 if a[0] in (False, None) else float(a[0]) if isinstance(a[0], (int, float)) else 0.0)

# VLOOKUP(LOOKUP, TABLE, COL, [RANGE_LOOKUP]) is handled specially because its
# table argument spans two columns.
XLOOKUP = Function('XLOOKUP', (3, 3), lambda ev, a: _fn_lookup(ev, a, a[0]))
VLOOKUP = Function('VLOOKUP', (3, 4), lambda ev, a: _fn_lookup(ev, [a[0], a[1].col(ev, 0), a[1].col(ev, int(a[2]) - 1)], a[0]))
INDEX = Function('INDEX', (2, 3), _fn_index)
MATCH = Function('MATCH', (2, 3), lambda ev, a: _fn_match(ev, a))
SUMPRODUCT = Function('SUMPRODUCT', None, lambda ev, a: _fn_sumproduct(ev, a))
MEDIAN = Function('MEDIAN', None, lambda ev, a: _fn_median(ev, a))
TEXTJOIN = Function('TEXTJOIN', (3, 3), lambda ev, a: _fn_textjoin(ev, a))
CONCAT = Function('CONCAT', None, lambda ev, a: ''.join(_str(v) for v in _flatten(a)))
LEN = Function('LEN', (1, 1), lambda ev, a: float(len(_str(a[0]))))
UPPER = Function('UPPER', (1, 1), lambda ev, a: _str(a[0]).upper())
LOWER = Function('LOWER', (1, 1), lambda ev, a: _str(a[0]).lower())
FUNCTIONS.update({f.name: f for f in (XLOOKUP, VLOOKUP, INDEX, MATCH, SUMPRODUCT, MEDIAN, TEXTJOIN, CONCAT, LEN, UPPER, LOWER)})


def _str(v):
    if v is None:
        return ''
    if isinstance(v, bool):
        return 'TRUE' if v else 'FALSE'
    if isinstance(v, float):
        return ('%f' % v).rstrip('0').rstrip('.')
    return str(v)


def _fn_match(ev, args):
    target, rng = args[0], args[1]
    if not isinstance(rng, RangeRef):
        raise FormulaError('REF')
    values = rng.values(ev)
    mode = int(_numeric_arg_values([args[2]], ev)[0]) if len(args) > 2 else 1
    for i, v in enumerate(values):
        if v == target:
            return float(i + 1)
        if mode > 0 and isinstance(v, (int, float)) and isinstance(target, (int, float)) and v <= target:
            pass
    raise FormulaError('N/A')


def _fn_sumproduct(ev, args):
    total = 0.0
    for a in args:
        if isinstance(a, RangeRef):
            total += sum(float(v) for v in a.values(ev) if isinstance(v, (int, float)) and not isinstance(v, bool))
        else:
            total += float(a)
    return total


def _fn_median(ev, args):
    nums = sorted(_numeric_arg_values(args, ev))
    if not nums:
        raise FormulaError('NUM')
    mid = len(nums) // 2
    return nums[mid] if len(nums) % 2 else (nums[mid - 1] + nums[mid]) / 2


def _fn_textjoin(ev, args):
    delim = _str(args[0])
    parts = [_str(v) for v in _flatten(args[2:] if isinstance(args[1], list) else args[1:]) if v not in (None, '')]
    return delim.join(parts)


def col_index(letters):
    n = 0
    for ch in letters.upper():
        n = n * 26 + (ord(ch) - 64)
    return n


class RangeRef:
    def __init__(self, sheet, c1, r1, c2, r2):
        self.sheet = sheet
        self.c1, self.r1, self.c2, self.r2 = c1, r1, c2, r2

    def cells(self):
        for r in range(self.r1, self.r2 + 1):
            for c in range(self.c1, self.c2 + 1):
                yield (self.sheet, c, r)

    def values(self, ev):
        return [ev.get(self.sheet, c, r) for (s, c, r) in self.cells()]

    def grid(self, ev):
        return [[ev.get(self.sheet, c, r) for c in range(self.c1, self.c2 + 1)] for r in range(self.r1, self.r2 + 1)]

    def col(self, ev, index):
        return [row[index] if 0 <= index < len(row) else None for row in self.grid(ev)]


class Parser:
    def __init__(self, text, ev):
        self.text = text
        self.ev = ev
        self.tokens = self._tokenize(text)
        self.i = 0

    @staticmethod
    def _tokenize(text):
        pos = 0
        tokens = []
        while pos < len(text):
            m = TOKEN_RE.match(text, pos)
            if not m or m.end() == pos:
                raise FormulaError('VALUE')
            pos = m.end()
            kind = m.lastgroup
            if kind == 'bad':
                raise FormulaError('VALUE')
            if kind is None:
                continue
            tokens.append((kind, m.group(kind), m.groupdict()))
        return tokens

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else (None, None, None)

    def take(self):
        tok = self.peek()
        self.i += 1
        return tok

    def expect(self, op):
        kind, value, _ = self.take()
        if kind != 'op' or value != op:
            raise FormulaError('VALUE')

    def parse(self):
        value = self.comparison()
        if self.i != len(self.tokens):
            raise FormulaError('VALUE')
        return value

    def comparison(self):
        left = self.concat()
        while True:
            kind, value, _ = self.peek()
            if kind == 'op' and value in ('=', '<>', '<', '>', '<=', '>='):
                self.take()
                right = self.concat()
                left = self._compare(value, left, right)
            else:
                return left

    def _compare(self, op, a, b):
        if isinstance(a, RangeRef):
            a = a.values(self.ev)[0]
        if isinstance(b, RangeRef):
            b = b.values(self.ev)[0]
        if isinstance(a, str) and isinstance(b, str):
            a, b = a.lower(), b.lower()
        elif isinstance(a, str) or isinstance(b, str):
            a, b = _str(a), _str(b)
        else:
            a, b = (a or 0), (b or 0)
        return {'=': a == b, '<>': a != b, '<': a < b, '>': a > b, '<=': a <= b, '>=': a >= b}[op]

    def concat(self):
        left = additive()
        while True:
            kind, value, _ = self.peek()
            if kind == 'op' and value == '&':
                self.take()
                left = _str(left) + _str(additive())
            else:
                return left

    def additive(self):
        left = multiplicative()
        while True:
            kind, value, _ = self.peek()
            if kind == 'op' and value in ('+', '-'):
                self.take()
                right = self.scalar(multiplicative())
                left = float(self.scalar(left)) + (float(right) if value == '+' else -float(right))
            else:
                return left

    def scalar(self, v):
        if isinstance(v, RangeRef):
            vals = v.values(self.ev)
            v = vals[0] if len(vals) == 1 else 0.0
        if v is None:
            return 0.0
        if isinstance(v, bool):
            return 1.0 if v else 0.0
        if isinstance(v, str):
            try:
                return float(v)
            except ValueError:
                raise FormulaError('VALUE')
        return float(v)

    def multiplicative(self):
        left = self.scalar(power())
        while True:
            kind, value, _ = self.peek()
            if kind == 'op' and value in ('*', '/'):
                self.take()
                right = self.scalar(power())
                if value == '*':
                    left = left * right
                else:
                    if right == 0:
                        raise FormulaError('DIV/0')
                    left = left / right
            else:
                return left

    def power(self):
        left = self.scalar(unary())
        while True:
            kind, value, _ = self.peek()
            if kind == 'op' and value == '^':
                self.take()
                left = left ** self.scalar(unary())
            else:
                return left

    def unary(self):
        kind, value, _ = self.peek()
        if kind == 'op' and value in ('-', '+'):
            self.take()
            v = self.scalar(unary())
            return -v if value == '-' else v
        return self.primary()

    def primary(self):
        kind, value, groups = self.take()
        if kind == 'num':
            return float(value)
        if kind == 'str':
            return value[1:-1].replace('""', '"')
        if kind == 'ref':
            return self._ref(groups)
        if kind == 'func':
            return self._call(groups)
        if kind == 'op' and value == '(':
            inner = self.comparison()
            self.expect(')')
            return inner
        raise FormulaError('VALUE')

    def _ref(self, groups):
        sheet = groups.get('sheet')
        if sheet:
            sheet = sheet[:-1].strip("'").replace("''", "'")
        start = groups['ref']
        kind, value, _ = self.peek()
        if kind == 'op' and value == ':':
            self.take()
            k2, v2, g2 = self.take()
            if k2 != 'ref':
                raise FormulaError('REF')
            end = v2
            bounds = list(_ref_cells(start)) + list(_ref_cells(end))
            (sc, sr), (ec, er) = bounds[0], bounds[-1]
            return RangeRef(sheet or self.ev.sheet, min(sc, ec), min(sr, er), max(sc, ec), max(sr, er))
        col, row = next(_ref_cells(start))
        return RangeRef(sheet or self.ev.sheet, col, row, col, row).values(self.ev)[0]

    def _call(self, groups):
        name = groups['func'].upper()
        args = []
        if self.peek()[1] == ')':
            self.take()
        else:
            while True:
                args.append(self._arg())
                kind, value, _ = self.take()
                if kind == 'op' and value == ',':
                    continue
                if kind == 'op' and value == ')':
                    break
                raise FormulaError('VALUE')
        if name == 'IFERROR':
            try:
                return self._force(args[0])
            except FormulaError as exc:
                return args[1]
        fn = FUNCTIONS.get(name)
        if fn is None:
            raise FormulaError('NAME?')
        try:
            return fn.call(args, self.ev)
        except FormulaError:
            raise
        except (ZeroDivisionError, ValueError, IndexError, TypeError):
            raise FormulaError('VALUE')

    def _arg(self):
        kind, value, _ = self.peek()
        if kind == 'op' and value in ('+', '-'):
            return self.unary()
        # Ranges must be resolved lazily for aggregate functions.
        saved = self.i
        kind, value, groups = self.peek()
        if kind in ('ref',):
            try:
                node = self.primary()
                nxt = self.peek()
                if not (isinstance(node, (int, float)) and (nxt[0] == 'op' and nxt[1] in ('+', '-', '*', '/', '^', '&', '='))):
                    return node
            except FormulaError:
                pass
            self.i = saved
        return self.comparison()

    def _force(self, v):
        if isinstance(v, RangeRef):
            vals = v.values(self.ev)
            return vals[0] if len(vals) == 1 else 0.0
        return v


def _ref_cells(ref):
    m = re.match(r'^\$?([A-Za-z]{1,3})\$?(\d+)$', ref)
    if not m:
        raise FormulaError('REF')
    return [(col_index(m.group(1)), int(m.group(2)))]


class Evaluator:
    """Lazy recursive evaluator over an ExcelSheet snapshot."""

    def __init__(self, sheet, reader):
        self.sheet = sheet
        self.reader = reader  # (sheet, col, row) -> raw value
        self.cache = {}
        self.visiting = set()

    def _key(self, sheet, c, r):
        title = sheet.title if hasattr(sheet, 'title') else sheet
        return (title, c, r)

    def resolve(self, sheet_title, c, r):
        return self.reader(sheet_title, c, r)

    def get(self, sheet, c, r):
        key = self._key(sheet, c, r)
        if key in self.cache:
            return self.cache[key]
        raw = self.reader(key[0], c, r)
        if isinstance(raw, str) and raw.startswith('='):
            if key in self.visiting:
                raise FormulaError('CIRC')
            self.visiting.add(key)
            try:
                value = Parser(raw[1:], _CellEval(self, key[0])).parse()
                value = _scalarize(value, self, key[0])
            finally:
                self.visiting.discard(key)
        else:
            value = raw
        self.cache[key] = value
        return value

    def cond(self, v):
        if isinstance(v, RangeRef):
            v = v.values(self._cell_ev_for_conditions)[0]
        if isinstance(v, str):
            return v.upper() not in ('', 'FALSE')
        return bool(v)


class _CellEval:
    """A per-cell view so RangeRef defaults resolve against the right sheet."""

    def __init__(self, evaluator, sheet):
        self.evaluator = evaluator
        self.sheet = sheet

    def get(self, sheet, c, r):
        return self.evaluator.get(sheet or self.sheet, c, r)

    def cond(self, v):
        return self.evaluator.cond(v)


def _scalarize(value, ev, sheet):
    if isinstance(value, RangeRef):
        vals = [ev.get(sheet, c, r) for (s, c, r) in value.cells()]
        return vals[0] if len(vals) == 1 else vals
    return value"}

{"content":""""Dependency-free Excel formula evaluator used as a self-checking aid.

Supports the common spreadsheet subset (arithmetic, comparisons, ranges and a
small function library). It mirrors Excel's left-to-right float evaluation so
observed values track an independent recalculation engine. It supplies no
business semantics: it only reports what a formula computes.
"""

import re
from decimal import Decimal, ROUND_HALF_UP


class FormulaError(Exception):
    def __init__(self, code):
        super().__init__(code)
        self.code = code


# ---------------------------------------------------------------- references

def col_index(letters):
    n = 0
    for ch in letters.upper():
        n = n * 26 + (ord(ch) - 64)
    return n


REF_RE = re.compile(r'^\$?([A-Za-z]{1,3})\$?(\d+)$')


def _ref_cell(ref):
    m = REF_RE.match(ref)
    if not m:
        raise FormulaError('REF')
    return col_index(m.group(1)), int(m.group(2))


class RangeRef:
    """A rectangular reference; values are fetched lazily from the reader."""

    def __init__(self, sheet, c1, r1, c2, r2):
        self.sheet = sheet
        self.c1, self.r1 = min(c1, c2), min(r1, r2)
        self.c2, self.r2 = max(c1, c2), max(r1, r2)

    def cells(self):
        for r in range(self.r1, self.r2 + 1):
            for c in range(self.c1, self.c2 + 1):
                yield c, r

    def values(self, ev, sheet=None):
        return [ev.get(sheet or self.sheet, c, r) for c, r in self.cells()]

    def grid(self, ev, sheet=None):
        return [
            [ev.get(sheet or self.sheet, c, r) for c in range(self.c1, self.c2 + 1)]
            for r in range(self.r1, self.r2 + 1)
        ]


# ------------------------------------------------------------------- helpers

def scalar(v):
    if isinstance(v, RangeRef):
        raise FormulaError('VALUE')
    if v is None:
        return 0.0
    if isinstance(v, bool):
        return 1.0 if v else 0.0
    if isinstance(v, str):
        try:
            return float(v)
        except ValueError:
            raise FormulaError('VALUE')
    return float(v)


def to_text(v):
    if v is None:
        return ''
    if isinstance(v, bool):
        return 'TRUE' if v else 'FALSE'
    if isinstance(v, float) and v.is_integer():
        return str(int(v))
    return str(v)


def flatten(values):
    out = []
    for v in values:
        if isinstance(v, list):
            out.extend(flatten(v))
        else:
            out.append(v)
    return out


def numeric_values(args, ev, sheet):
    """Excel aggregates: ranges ignore non-numbers; scalars coerce."""
    out = []
    for a in args:
        if isinstance(a, RangeRef):
            for v in a.values(ev, sheet):
                if isinstance(v, bool):
                    out.append(float(v))
                elif isinstance(v, (int, float)):
                    out.append(float(v))
        elif isinstance(a, list):
            for v in flatten(a):
                if isinstance(v, bool):
                    out.append(float(v))
                elif isinstance(v, (int, float)):
                    out.append(float(v))
        else:
            out.append(scalar(a))
    return out


def _round(value, digits):
    q = Decimal(1).scaleb(-int(digits))
    return float(Decimal(repr(float(value))).quantize(q, rounding=ROUND_HALF_UP))


def _flattened(argv, start=0):
    return [v for v in flatten(argv[start:]) if v is not None]


def _lookup_exact(target, keys, rets):
    if isinstance(target, str):
        try:
            target = float(target)
        except ValueError:
            pass
    for k, r in zip(keys, rets):
        if k == target:
            return r
    raise FormulaError('N/A')


# ----------------------------------------------------------------- functions

class Fn:
    def __init__(self, name, arity, impl):
        self.name = name
        self.arity = arity  # (min, max) or None for variadic
        self.impl = impl

    def call(self, argv, ev, sheet):
        if self.arity is not None:
            lo, hi = self.arity
            if not (lo <= len(argv) <= hi):
                raise FormulaError('VALUE')
        for a in argv:
            if isinstance(a, RangeRef) and a.sheet is None:
                a.sheet = sheet
        try:
            return self.impl(argv, ev, sheet)
        except FormulaError:
            raise
        except (ZeroDivisionError, ValueError, IndexError, TypeError, OverflowError):
            raise FormulaError('VALUE')


def _fn_if(argv, ev, sheet):
    condition = argv[0]
    if isinstance(condition, RangeRef):
        condition = condition.values(ev, sheet)[0]
    truthy = (
        condition.upper() not in ('', 'FALSE')
        if isinstance(condition, str)
        else bool(condition)
    )
    if truthy:
        return _deref(argv[1], ev, sheet) if len(argv) > 1 else True
    return _deref(argv[2], ev, sheet) if len(argv) > 2 else False


def _deref(v, ev, sheet):
    if isinstance(v, RangeRef):
        return v.values(ev, sheet)[0]
    return v


def _fn_xlookup(argv, ev, sheet):
    target, look, ret = argv[0], argv[1], argv[2]
    if not isinstance(look, RangeRef) or not isinstance(ret, RangeRef):
        raise FormulaError('REF')
    keys = look.values(ev, sheet)
    rets = ret.values(ev, sheet)
    return _lookup_exact(target, keys, rets)


def _fn_vlookup(argv, ev, sheet):
    if not isinstance(argv[1], RangeRef):
        raise FormulaError('REF')
    table = argv[1]
    col = int(scalar(argv[2]))
    keys = [row[0] for row in table.grid(ev, sheet)]
    rets = [row[col - 1] if 0 <= col - 1 < len(row) else None for row in table.grid(ev, sheet)]
    return _lookup_exact(argv[0], keys, rets)


def _fn_index(argv, ev, sheet):
    rng = argv[0]
    if not isinstance(rng, RangeRef):
        raise FormulaError('REF')
    row = int(scalar(argv[1]))
    col = int(scalar(argv[2])) if len(argv) > 2 else 1
    grid = rng.grid(ev, sheet)
    if not (1 <= row <= len(grid)) or not (1 <= col <= len(grid[0])):
        raise FormulaError('REF')
    return grid[row - 1][col - 1]


def _fn_match(argv, ev, sheet):
    target, rng = argv[0], argv[1]
    if not isinstance(rng, RangeRef):
        raise FormulaError('REF')
    for i, v in enumerate(rng.values(ev, sheet)):
        if v == target:
            return float(i + 1)
    raise FormulaError('N/A')


def _fn_sumproduct(argv, ev, sheet):
    total = 0.0
    for a in argv:
        if isinstance(a, RangeRef):
            total += sum(float(v) for v in a.values(ev, sheet) if isinstance(v, (int, float)) and not isinstance(v, bool))
        else:
            total += scalar(a)
    return total


def _fn_median(argv, ev, sheet):
    nums = sorted(numeric_values(argv, ev, sheet))
    if not nums:
        raise FormulaError('NUM')
    mid = len(nums) // 2
    return nums[mid] if len(nums) % 2 else (nums[mid - 1] + nums[mid]) / 2


def _fn_iferror(argv, ev, sheet):
    try:
        return _deref(argv[0], ev, sheet)
    except FormulaError:
        return _deref(argv[1], ev, sheet)


def _fn_textjoin(argv, ev, sheet):
    delim = to_text(_deref(argv[0], ev, sheet))
    items = _flattened(argv, 1)
    return delim.join(to_text(v) for v in items)


def _fn_n(argv, ev, sheet):
    v = _deref(argv[0], ev, sheet)
    if isinstance(v, bool):
        return 1.0 if v else 0.0
    return float(v) if isinstance(v, (int, float)) else 0.0


FUNCTIONS = {
    'SUM': Fn('SUM', None, lambda a, ev, s: float(sum(numeric_values(a, ev, s)))),
    'MIN': Fn('MIN', None, lambda a, ev, s: min(numeric_values(a, ev, s) or [0.0])),
    'MAX': Fn('MAX', None, lambda a, ev, s: max(numeric_values(a, ev, s) or [0.0])),
    'AVERAGE': Fn('AVERAGE', None, lambda a, ev, s: sum(numeric_values(a, ev, s)) / len(numeric_values(a, ev, s) or [0.0]) if numeric_values(a, ev, s) else (_ for _ in ()).throw(FormulaError('DIV/0'))),
    'COUNT': Fn('COUNT', None, lambda a, ev, s: float(len(numeric_values(a, ev, s)))),
    'ABS': Fn('ABS', (1, 1), lambda a, ev, s: abs(scalar(_deref(a[0], ev, s)))),
    'ROUND': Fn('ROUND', (2, 2), lambda a, ev, s: _round(scalar(_deref(a[0], ev, s)), scalar(_deref(a[1], ev, s)))),
    'IF': Fn('IF', (2, 3), _fn_if),
    'IFERROR': Fn('IFERROR', (2, 2), _fn_iferror),
    'XLOOKUP': Fn('XLOOKUP', (3, 3), _fn_xlookup),
    'VLOOKUP': Fn('VLOOKUP', (3, 4), _fn_vlookup),
    'INDEX': Fn('INDEX', (2, 3), _fn_index),
    'MATCH': Fn('MATCH', (2, 3), _fn_match),
    'SUMPRODUCT': Fn('SUMPRODUCT', None, _fn_sumproduct),
    'MEDIAN': Fn('MEDIAN', None, _fn_median),
    'TEXTJOIN': Fn('TEXTJOIN', (2, 3), _fn_textjoin),
    'CONCAT': Fn('CONCAT', None, lambda a, ev, s: ''.join(to_text(v) for v in _flattened(a))),
    'LEN': Fn('LEN', (1, 1), lambda a, ev, s: float(len(to_text(_deref(a[0], ev, s))))),
    'UPPER': Fn('UPPER', (1, 1), lambda a, ev, s: to_text(_deref(a[0], ev, s)).upper()),
    'LOWER': Fn('LOWER', (1, 1), lambda a, ev, s: to_text(_deref(a[0], ev, s)).lower()),
    'N': Fn('N', (1, 1), _fn_n),
    'MINUS': Fn('MINUS', (2, 2), lambda a, ev, s: scalar(_deref(a[0], ev, s)) - scalar(_deref(a[1], ev, s))),
