# -------------------------------------------------------------------- parser

TOKEN_RE = re.compile(
    r'\s*(?:'
    r'(?P<num>\d+(?:\.\d*)?(?:[eE][+-]?\d+)?|\.\d+)'
    r'|(?P<func>[A-Za-z_][A-Za-z0-9_.]*)\s*\('
    r'|(?:(?P<sheet>\'(?:[^\']|\'\')*\'|[A-Za-z_][A-Za-z0-9_.]*)!)?(?P<ref>\$?[A-Za-z]{1,3}\$?\d+)'
    r'|(?P<op><>|<=|>=|[-+*/^&=<>(),:%])'
    r'|(?P<str>"(?:[^"]|"")*")'
    r'|(?P<bad>\S))'
)


def tokenize(text):
    pos = 0
    tokens = []
    while pos < len(text):
        m = TOKEN_RE.match(text, pos)
        if not m or m.end() == pos:
            raise FormulaError('VALUE')
        pos = m.end()
        if m.lastgroup == 'bad':
            raise FormulaError('VALUE')
        tokens.append((m.lastgroup, m.group(m.lastgroup), m.groupdict()))
    return tokens


class Parser:
    def __init__(self, text, ev, sheet):
        self.tokens = tokenize(text)
        self.ev = ev
        self.sheet = sheet
        self.i = 0

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else (None, None, {})

    def take(self):
        tok = self.peek()
        self.i += 1
        return tok

    def expect(self, op):
        kind, value, _ = self.take()
        if kind != 'op' or value != op:
            raise FormulaError('VALUE')

    def parse(self):
        value = self.comparison()
        if self.i != len(self.tokens):
            raise FormulaError('VALUE')
        return value

    # An argument keeps its RangeRef shape unless it is consumed by an operator.
    def comparison(self):
        left = self.concat()
        while True:
            kind, value, _ = self.peek()
            if kind == 'op' and value in ('=', '<>', '<', '>', '<=', '>='):
                self.take()
                left = self._compare(value, self.deref(left), self.deref(self.concat()))
            else:
                return left

    def _compare(self, op, a, b):
        if isinstance(a, str) and isinstance(b, str):
            a, b = a.lower(), b.lower()
        elif isinstance(a, str) or isinstance(b, str):
            a, b = to_text(a), to_text(b)
        else:
            a, b = a or 0, b or 0
        return {'=': a == b, '<>': a != b, '<': a < b, '>': a > b, '<=': a <= b, '>=': a >= b}[op]

    def concat(self):
        left = self.additive()
        while True:
            kind, value, _ = self.peek()
            if kind == 'op' and value == '&':
                self.take()
                right = self.additive()
                left = to_text(self.deref(left)) + to_text(self.deref(right))
            else:
                return left

    def additive(self):
        left = self.multiplicative()
        while True:
            kind, value, _ = self.peek()
            if kind == 'op' and value in ('+', '-'):
                self.take()
                right = self.multiplicative()
                a, b = scalar(self.deref(left)), scalar(self.deref(right))
                left = a + b if value == '+' else a - b
            else:
                return left

    def multiplicative(self):
        left = self.power()
        while True:
            kind, value, _ = self.peek()
            if kind == 'op' and value in ('*', '/'):
                self.take()
                right = self.power()
                a, b = scalar(self.deref(left)), scalar(self.deref(right))
                if value == '*':
                    left = a * b
                else:
                    if b == 0:
                        raise FormulaError('DIV/0')
                    left = a / b
            else:
                return left

    def power(self):
        left = self.unary()
        while True:
            kind, value, _ = self.peek()
            if kind == 'op' and value == '^':
                self.take()
                left = scalar(self.deref(left)) ** scalar(self.deref(self.unary()))
            else:
                return left

    def unary(self):
        kind, value, _ = self.peek()
        if kind == 'op' and value in ('-', '+'):
            self.take()
            v = scalar(self.deref(self.unary()))
            return -v if value == '-' else v
        return self.primary()

    def deref(self, v):
        if isinstance(v, RangeRef):
            return v.values(self.ev, self.sheet)[0]
        return v

    def primary(self):
        kind, value, groups = self.take()
        if kind == 'num':
            return float(value)
        if kind == 'str':
            return value[1:-1].replace('""', '"')
        if kind == 'ref':
            return self._ref(groups)
        if kind == 'func':
            return self._call(groups, value)
        if kind == 'op' and value == '(':
            inner = self.comparison()
            self.expect(')')
            return inner
        raise FormulaError('VALUE')

    def _ref(self, groups):
        sheet = groups.get('sheet')
        if sheet:
            sheet = sheet[:-1]
            sheet = sheet[1:-1].replace("''", "'") if sheet.startswith("'") else sheet
        c, r = _ref_cell(groups['ref'])
        kind, value, _ = self.peek()
        if kind == 'op' and value == ':':
            self.take()
            k2, v2, g2 = self.take()
            if k2 != 'ref':
                raise FormulaError('REF')
            c2, r2 = _ref_cell(v2)
            return RangeRef(sheet or self.sheet, c, r, c2, r2)
        return RangeRef(sheet or self.sheet, c, r, c, r)

    def _call(self, groups, raw_name):
        name = raw_name.upper()
        args = []
        if self.peek()[0] == 'op' and self.peek()[1] == ')':
            self.take()
        else:
            while True:
                args.append(self.comparison())
                kind, value, _ = self.take()
                if kind == 'op' and value == ',':
                    continue
                if kind == 'op' and value == ')':
                    break
                raise FormulaError('VALUE')
        fn = FUNCTIONS.get(name)
        if fn is None:
            raise FormulaError('NAME?')
        return fn.call(args, self.ev, self.sheet)


# ----------------------------------------------------------------- evaluator

class Evaluator:
    """Lazy, memoized evaluation over a reader of raw cell values."""

    def __init__(self, reader):
        self.reader = reader  # (sheet_title, col, row) -> raw value
        self.cache = {}
        self.visiting = set()

    def get(self, sheet, c, r):
        key = (sheet, c, r)
        if key in self.cache:
            return self.cache[key]
        raw = self.reader(sheet, c, r)
        if isinstance(raw, str) and raw.startswith('='):
            if key in self.visiting:
                raise FormulaError('CIRC')
            self.visiting.add(key)
            try:
                value = Parser(raw[1:], self, sheet).parse()
                value = self._scalarize(value)
            finally:
                self.visiting.discard(key)
        else:
            value = raw
        self.cache[key] = value
        return value

    def _scalarize(self, value):
        if isinstance(value, RangeRef):
            vals = value.values(self)
            return vals[0] if len(vals) == 1 else vals
        return value

    def evaluate_raw(self, raw, sheet):
        """Evaluate a formula string in isolation without memoizing it."""
        return self._scalarize(Parser(raw[1:], self, sheet).parse())","file_path":"/workspace/v1-recalc/formula_engine.py"}

{"content":""""Workbook operations: inspect, write, calculate, verify, and cell metadata.

Operations never invent business semantics. `calculate` and `verify` run an
independent recalculation (headless LibreOffice) and a local formula evaluator
so a caller can observe what the workbook actually computes.
"""

import json
import os
import shutil
import subprocess
from pathlib import Path

from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
from openpyxl.utils.cell import coordinate_to_tuple, range_boundaries

from formula_engine import Evaluator, FormulaError, to_text

WORKSPACE = Path('/workspace')
CENT_PER_DOLLAR = 100


class OperationError(ValueError):
    pass


# ------------------------------------------------------------------ helpers

def _workspace_path(path, label):
    target = Path(path).expanduser()
    if not target.is_absolute():
        target = (WORKSPACE / target)
    target = target.resolve()
    if target != WORKSPACE and not target.is_relative_to(WORKSPACE):
        raise OperationError(f'{label} must be inside /workspace: {target}')
    return target


def _number_text(value):
    if isinstance(value, float):
        text = f'{value:.10f}'.rstrip('0').rstrip('.')
        return text or '0'
    return str(value)


def _cell_json(value):
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return _number_text(value) if isinstance(value, float) else str(value)
    return to_text(value)


def _occupied(sheet, include_comments=True):
    rows = []
    for row in sheet.iter_rows():
        for cell in row:
            comment = cell.comment.text if cell.comment else None
            if cell.value is None and not (comment and include_comments):
                continue
            entry = {
                'cell': cell.coordinate,
                'value': _cell_json(cell.value),
                'type': 'formula' if isinstance(cell.value, str) and cell.value.startswith('=') else _cell_json(type(cell.value).__name__),
            }
            if cell.data_type == 'f':
                entry['type'] = 'formula'
            if comment:
                entry['comment'] = comment
            rows.append(entry)
    return rows


def _sheet_map(workbook):
    return {sheet.title: sheet for sheet in workbook}


# ------------------------------------------------------------------- inspect

def op_inspect(args):
    workbook = load_workbook(args['file'])
    sheets = {}
    for sheet in workbook.worksheets:
        rows = _occupied(sheet)
        sheets[sheet.title] = {
            'dimensions': sheet.dimensions,
            'max_row': sheet.max_row,
            'max_column': sheet.max_column,
            'merged': [str(r) for r in sheet.merged_cells.ranges],
            'cells': rows,
        }
    return {
        'sheets': sheets,
        'sheet_order': [s.title for s in workbook.worksheets],
        'defined_names': [name for name in workbook.defined_names],
        'note': 'Source labels are facts; this operation does not infer business semantics.',
    }


# --------------------------------------------------------------------- write

def _apply_edits(workbook, edits, formats=None):
    sheets = _sheet_map(workbook)
    seen = set()
    for edit in edits:
        sheet = sheets.get(edit['sheet'])
        if sheet is None:
            raise OperationError(f"Unknown sheet: {edit['sheet']}")
        position = (edit['sheet'], coordinate_to_tuple(edit['cell']))
        if position in seen:
            raise OperationError(f"Duplicate target: {edit['sheet']}!{edit['cell']}")
        seen.add(position)
        sheet[edit['cell']] = edit['value']
    for spec in formats or []:
        sheet = sheets.get(spec['sheet'])
        if sheet is None:
            raise OperationError(f"Unknown sheet: {spec['sheet']}")
        for cell in sheet[spec['range']]:
            for member in (cell if isinstance(cell, tuple) else (cell,)):
                if 'number_format' in spec:
                    member.number_format = spec['number_format']
                if spec.get('bold') is not None:
                    font = member.font.copy(bold=bool(spec['bold']))
                    member.font = font
                if 'column_width' in spec and member.column == range_boundaries(spec['range'])[0]:
                    pass
    return len(seen)


def op_write(args):
    target = _workspace_path(args['destination'], 'destination')
    if target.suffix.lower() != '.xlsx':
        raise OperationError('destination must be an .xlsx file')
    workbook = load_workbook(args['source'])
    count = _apply_edits(workbook, args['edits'], args.get('formats'))
    target.parent.mkdir(parents=True, exist_ok=True)
    workbook.save(target)
    return {'saved': str(target), 'submitted_cells': count, 'formula_values_recalculated': False}


# ------------------------------------------------------------------ formulas

def op_calculate(args):
    """Recalculate with an independent engine and report cached results."""
    source = _workspace_path(args['file'], 'file')
    if not source.exists():
        raise OperationError(f'No such workbook: {source}')
    with tempfile_dir() as workdir:
        outdir = Path(workdir) / 'recalculated'
        outdir.mkdir()
        _recalculate(source, outdir, timeout=int(args.get('timeout_seconds') or 90))
        recalculated = outdir / source.name
        if not recalculated.exists():
            raise OperationError('Recalculation engine produced no workbook')
        workbook = load_workbook(recalculated, data_only=True)
        formulas = load_workbook(source, data_only=False)
        requested = _scope(args.get('range'))
        values = {}
        errors = []
        for title, spec in requested.items():
            sheet = workbook[title] if title in workbook.sheetnames else None
            fsheet = formulas[title] if title in formulas.sheetnames else None
            if sheet is None or fsheet is None:
                errors.append(f'unknown sheet {title}')
                continue
            for coord in _expand(fsheet, spec):
                cached = sheet[coord].value
                raw = fsheet[coord].value
                values[coord] = _cell_json(cached) if cached is not None else None
                if isinstance(cached, str) and cached.startswith('#'):
                    errors.append(coord)
                if isinstance(raw, str) and raw.startswith('=') and cached is None:
                    values[coord] = None
        return {
            'file': str(source),
            'engine': 'libreoffice headless recalculation',
            'values': values,
            'range_errors': errors,
            'formula_values_recalculated': True,
        }


def op_verify(args):
    """Compare independent recalculated values with the workbook's cached ones."""
    source = _workspace_path(args['file'], 'file')
    if not source.exists():
        raise OperationError(f'No such workbook: {source}')
    with tempfile_dir() as workdir:
        outdir = Path(workdir) / 'recalculated'
        outdir.mkdir()
        _recalculate(source, outdir, timeout=int(args.get('timeout_seconds') or 90))
        recalculated = outdir / source.name
        reference = load_workbook(recalculated, data_only=True) if recalculated.exists() else None
        formulas = load_workbook(source, data_only=False)
        cached_wb = load_workbook(source, data_only=True)
        sheet_readers = {}
        for sheet in formulas.worksheets:
            sheet_readers[sheet.title] = sheet

        def reader(title, col, row):
            sheet = sheet_readers.get(title)
            if sheet is None:
                return None
            return sheet.cell(row=row, column=col).value

        local = Evaluator(reader)
        requested = _scope(args.get('range'))
        results = []
        for title, spec in requested.items():
            if title not in sheet_readers:
                results.append({'sheet': title, 'error': 'unknown sheet'})
                continue
            for coord in _expand(sheet_readers[title], spec):
                cached = cached_wb[title][coord].value if reference is not None else None
                try:
                    if reference is not None:
                        reference_value = reference[title][coord].value
                    else:
                        reference_value = None
                except KeyError:
                    reference_value = None
                try:
                    local_value = local.get(title, *coordinate_to_tuple(coord)[::-1])
                except FormulaError as exc:
                    local_value = '#' + exc.code
                status = 'no-formula'
                raw = sheet_readers[title][coord].value
                if isinstance(raw, str) and raw.startswith('='):
                    status = 'unverified' if reference_value is None else 'ok'
                    if reference_value is not None and not _matches(reference_value, local_value):
                        status = 'mismatch'
                results.append({
                    'sheet': title,
                    'cell': coord,
                    'formula': raw if isinstance(raw, str) and raw.startswith('=') else None,
                    'cached': _cell_json(cached) if cached is not None else None,
                    'recalculated': _cell_json(reference_value) if reference_value is not None else None,
                    'local': _cell_json(local_value) if local_value is not None else None,
                    'status': status,
                })
        mismatches = [r for r in results if r.get('status') == 'mismatch']
        formula_cells = [r for r in results if r.get('formula')]
        return {
            'file': str(source),
            'engine': 'libreoffice headless recalculation + local formula evaluator',
            'checked_cells': len(results),
            'formula_cells': len(formula_cells),
            'verification': 'independent' if reference is not None else 'unavailable',
            'mismatches': mismatches,
            'results': results,
        }


def _matches(reference, local, tolerance=1e-9):
    if isinstance(reference, (int, float)) and not isinstance(reference, bool):
        if isinstance(local, (int, float)) and not isinstance(local, bool):
            return abs(float(reference) - float(local)) <= tolerance * max(1.0, abs(float(reference)))
        return False
    if isinstance(reference, str) and isinstance(local, str):
        return reference.strip().lower() == local.strip().lower()
    return reference == local


def _scope(spec):
    if not spec:
        return None
    return spec if isinstance(spec, dict) else {}


def _expand(sheet, spec):
    if sheet is None:
        return []
    if spec and spec.get('range'):
        rows = sheet[spec['range']]
        return [c.coordinate for row in rows for c in (row if isinstance(row, tuple) else (row,))]
    out = []
    for row in sheet.iter_rows():
        for cell in row:
            out.append(cell.coordinate)
    return out


# ---------------------------------------------------- recalculation utility

class tempfile_dir:
    def __enter__(self):
        import tempfile
        self._dir = tempfile.mkdtemp(prefix='workbook-')
        return self._dir

    def __exit__(self, *exc):
        shutil.rmtree(self._dir, ignore_errors=True)
        return False


def _find_office():
    for name in ('libreoffice', 'soffice'):
        found = shutil.which(name)
        if found:
            return found
    return None


def _recalculate(source, outdir, timeout=90):
    office = _find_office()
    if office is None:
        raise OperationError('No recalculation engine (libreoffice/soffice) is available')
    env = dict(os.environ)
    env.setdefault('HOME', str(Path(outdir) / 'home'))
    Path(env['HOME']).mkdir(parents=True, exist_ok=True)
    env['SAL_USE_VCLPLUGIN'] = 'svp'
    profile = f'-env:UserInstallation=file://{Path(outdir) / "profile"}'
    command = [office, '--headless', '--norestore', '--nolockcheck', profile,
               '--convert-to', 'xlsx', '--outdir', str(outdir), str(source)]
    try:
        subprocess.run(command, check=True, timeout=timeout, capture_output=True, env=env)
    except subprocess.TimeoutExpired:
        raise OperationError('Recalculation engine timed out')
    except subprocess.CalledProcessError as exc:
        detail = (exc.stderr or b'').decode('utf-8', 'replace')[:500]
        raise OperationError(f'Recalculation engine failed: {detail}')


# ------------------------------------------------------------- cell metadata

def op_cells(args):
    workbook = load_workbook(args['file'])
    out = {}
    for title in workbook.sheetnames:
        if args.get('sheet') and title != args['sheet']:
            continue
        sheet = workbook[title]
        cells = {}
        for row in sheet.iter_rows():
            for cell in row:
                if cell.value is None and not cell.comment:
                    continue
                cells[cell.coordinate] = {
                    'value': _cell_json(cell.value),
                    'data_type': cell.data_type,
                    'number_format': cell.number_format,
                    'bold': bool(cell.font.bold),
                    'bold_explicit': bool(getattr(cell.font, 'bold', False)) and cell.font.__dict__.get('b', None) is not None,
                    'comment': cell.comment.text if cell.comment else None,
