import json
import sys

from workbook_ops import OPS


def main():
    args = json.load(sys.stdin)
    operation = args.get('operation')
    handler = OPS.get(operation)
    if handler is None:
        print(json.dumps({'error': f'Unknown workbook operation: {operation}'}))
        return 1
    try:
        result = handler(args)
    except (ValueError, OSError) as exc:
        print(json.dumps({'error': str(exc)}))
        return 1
    print(json.dumps(result, default=str))
    return 0


if __name__ == '__main__':
    sys.exit(main())","file_path":"/workspace/v1-recalc/workbook.py"}

