{"content":"import { defineTool } from '@deepseek-ai/dsh-tools';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';

export const inject = ['tools'];

/**
 * Run one workbook operation in an isolated Python process and return its
 * JSON reply. Failures surface as rejected promises, which the tool registry
 * materializes as error results.
 */
function createInvoker() {
  const script = fileURLToPath(new URL('./workbook.py', import.meta.url));
  return (args, signal) =>
    new Promise((resolve, reject) => {
      const child = spawn('python3', [script], { signal, stdio: ['pipe', 'pipe', 'pipe'] });
      const out = [];
      const err = [];
      child.stdout.on('data', (chunk) => out.push(chunk));
      child.stderr.on('data', (chunk) => err.push(chunk));
      child.on('error', reject);
      child.on('close', (code) => {
        const text = Buffer.concat(out).toString();
        if (code !== 0) {
          let message = Buffer.concat(err).toString();
          try {
            const parsed = JSON.parse(text);
            if (parsed && typeof parsed.error === 'string') message = parsed.error;
          } catch {
            /* keep stderr message */
          }
          reject(new Error(message || `workbook operation exited with code ${code}`));
          return;
        }
        resolve(text);
      });
      child.stdin.end(JSON.stringify(args));
    });
}

const textOutput = {
  schema: { type: 'string' },
  render: (_args, value) => [{ type: 'text', text: value }],
};

export function apply(ctx) {
  const invoke = createInvoker();

  ctx.tools.register(
    defineTool({
      name: 'workbook_inspect',
      description:
        'Read exact occupied cells, values, formulas and comments in an XLSX workbook, plus sheet order, dimensions and merged ranges. Source labels are facts; this tool does not infer business semantics.',
      parameters: { file: { type: 'string', required: true } },
      output: textOutput,
      execute: (args, exec) => invoke({ operation: 'inspect', ...args }, exec.signal),
    }),
  );

  ctx.tools.register(
    defineTool({
      name: 'workbook_write',
      description:
        'Apply explicit caller-supplied values or formulas to a copy of an XLSX workbook, optionally setting number formats on ranges. Original inputs are preserved; destination must be inside /workspace. Does not calculate formulas.',
      parameters: {
        source: { type: 'string', required: true },
        destination: { type: 'string', required: true },
        edits: {
          type: 'array',
          required: true,
          items: {
            type: 'object',
            additionalProperties: false,
            properties: {
              sheet: { type: 'string', required: true },
              cell: { type: 'string', required: true },
              value: { type: 'json', required: true },
            },
          },
        },
        formats: {
          type: 'array',
          items: {
            type: 'object',
            additionalProperties: false,
            properties: {
              sheet: { type: 'string', required: true },
              range: { type: 'string', required: true },
              number_format: { type: 'string' },
            },
          },
        },
      },
      output: textOutput,
      execute: (args, exec) => invoke({ operation: 'write', ...args }, exec.signal),
    }),
  );

  ctx.tools.register(
    defineTool({
      name: 'workbook_calculate',
      description:
        'Recalculate every formula in an XLSX workbook with an independent headless office engine and return the resulting values, so formulas can be checked without trusting a saved cache. Reports # error values. Does not judge business correctness.',
      parameters: {
        file: { type: 'string', required: true },
        range: {
          type: 'object',
          description: 'Optional sheet-to-A1-range map limiting the reported cells.',
          additionalProperties: true,
          properties: {},
        },
      },
      output: textOutput,
      execute: (args, exec) => invoke({ operation: 'calculate', ...args }, exec.signal),
    }),
  );

  ctx.tools.register(
    defineTool({
      name: 'workbook_verify',
      description:
        'Cross-check an XLSX workbook: recalculate with an independent office engine, re-evaluate each formula with a second local evaluator, and compare them with the values cached in the file. Returns per-cell status (ok, mismatch, unverified) plus discrepancies.',
      parameters: {
        file: { type: 'string', required: true },
        range: {
          type: 'object',
          description: 'Optional sheet-to-A1-range map limiting the checked cells.',
          additionalProperties: true,
          properties: {},
        },
      },
      output: textOutput,
      execute: (args, exec) => invoke({ operation: 'verify', ...args }, exec.signal),
    }),
  );

  ctx.tools.register(
    defineTool({
      name: 'workbook_cells',
      description:
        'Report cell metadata that values alone do not show: number formats, bold formatting, merged membership, protection and comments per sheet.',
      parameters: {
        file: { type: 'string', required: true },
        sheet: { type: 'string' },
      },
      output: textOutput,
      execute: (args, exec) => invoke({ operation: 'cells', ...args }, exec.signal),
    }),
  );
}","file_path":"/workspace/v1-recalc/index.mjs"}

