_LAYOUT_HINTS = (
    ('blank_row_between', 'a blank row separates this label from earlier rows'),
    ('header_row', 'top row carries period headers rather than values'),
    ('dash_placeholder', 'label contains a dash or slash placeholder such as X-X or X/Y'),
    ('intentional_blank', 'label states a cell is intentionally blank'),
    ('no_fill', 'label forbids filling or populating a cell'),
)


def _is_blank(value):
    return value is None or (isinstance(value, str) and not value.strip())


def _label_shape(text):
    """Describe a label's structure without attributing business meaning."""
    parts = [p for p in __import__('re').split(r'[\s\-–—/()\[\]:,]+', text) if p]
    shape = [{'word': p, 'case': 'upper' if p.isupper() else 'title' if p[:1].isupper() else 'lower',
              'alnum': any(ch.isalnum() for ch in p), 'digits': any(ch.isdigit() for ch in p)}
             for p in parts]
    return shape


def _notes(text, keywords):
    """List which caller-supplied keywords appear in a comment."""
    lowered = text.lower()
    return [k for k in keywords if k and k.lower() in lowered]


def op_profile(args):
    workbook = load_workbook(args['file'])
    keywords = args.get('keywords') or []
    if isinstance(keywords, str):
        keywords = [keywords]
    profile = {}
    for sheet in workbook.worksheets:
        rows = {}
        for row in sheet.iter_rows():
            values = [(c.coordinate, c.value) for c in row]
            if all(_is_blank(v) for _, v in values):
                rows[str(row[0].row)] = {'kind': 'blank_row'}
                continue
            cells = {}
            for cell in row:
                if _is_blank(cell.value) and not cell.comment:
                    continue
                entry = {
                    'value': _cell_json(cell.value),
                    'column': cell.column_letter,
                    'is_formula': isinstance(cell.value, str) and cell.value.startswith('='),
                    'number_format': cell.number_format,
                }
                if not isinstance(cell.value, str):
                    entry['kind'] = 'input'
                elif isinstance(cell.value, str) and cell.value.startswith('='):
                    entry['kind'] = 'formula'
                elif _is_blank(cell.value):
                    entry['kind'] = 'blank_with_comment'
                else:
                    entry['kind'] = 'label' if cell.column == 1 or len(cell.value) > 0 else 'text'
                if cell.comment:
                    entry['comment'] = cell.comment.text
                    if keywords:
                        entry['matched_keywords'] = _notes(cell.comment.text, keywords)
                cells[cell.coordinate] = entry
            rows[str(row[0].row)] = {'kind': 'data_row', 'cells': cells}
        profile[sheet.title] = {
            'max_row': sheet.max_row,
            'max_column': sheet.max_column,
            'rows': rows,
        }
    return {
        'file': str(args['file']),
        'sheets': profile,
        'layout_hints': [{'hint': k, 'meaning': m} for k, m in _LAYOUT_HINTS],
        'note': 'Structural description only: labels, comments, blanks and types. No business meaning is inferred.',
    }


OPS = {
    'inspect': op_inspect,
    'profile': op_profile,"}

